        if (res.discount > 0) {
            sb.append("Desconto: ").append(formatPTCurrency(res.discount)).append("\n");
        }

        sb.append("Total: ").append(formatPTCurrency(res.total)).append("\n");
        sb.append("ISS retido (5%): ").append(formatPTCurrency(iss));

        return sb.toString();
    }

