            pstmt.setInt(1, roomNumber);
            pstmt.setString(2, checkOut);
            pstmt.setString(3, checkIn);

            try (ResultSet rs = pstmt.executeQuery()) {
                if (rs.next()) {
                    return rs.getInt("count") == 0;
                }
            }
        }

        return false;
    }

